(function(E){ const x = E["exam-02"] = E["exam-02"] || {units:{}}; (x.units = x.units || {})["x02-l4"] = {"id":"x02-l4","patterns":["L4-society","PARA-signpost"],"title":{"en":"Listening Part 4: a presentation","tr":"Listening Part 4: bir sunum","fa":"Listening Part 4: یک ارائه"},"objective":{"en":"In this lesson you will learn to complete ten notes during a student presentation with no break: use the headings and the speaker’s signposts to keep your place, and write one word in the form you hear.","tr":"Bu derste arasız bir öğrenci sunumu sırasında on notu tamamlamayı öğreneceksin: yerini kaybetmemek için başlıkları ve konuşanın yön gösteren ifadelerini kullanacak ve tek kelimeyi duyduğun biçimde yazacaksın.","fa":"در این درس یاد می‌گیری در طول ارائه‌ی یک دانشجو که مکث ندارد، ده یادداشت را کامل کنی: با کمک عنوان‌ها و جمله‌های راهنمای گوینده جایت را گم نکنی و یک کلمه را به همان شکلی که می‌شنوی بنویسی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 4: a presentation","tr":"Listening Part 4: bir sunum","fa":"Listening Part 4: یک ارائه"},"objective":{"en":"In this lesson you will learn to complete ten notes during a student presentation with no break: use the headings and the speaker’s signposts to keep your place, and write one word in the form you hear.","tr":"Bu derste arasız bir öğrenci sunumu sırasında on notu tamamlamayı öğreneceksin: yerini kaybetmemek için başlıkları ve konuşanın yön gösteren ifadelerini kullanacak ve tek kelimeyi duyduğun biçimde yazacaksın.","fa":"در این درس یاد می‌گیری در طول ارائه‌ی یک دانشجو که مکث ندارد، ده یادداشت را کامل کنی: با کمک عنوان‌ها و جمله‌های راهنمای گوینده جایت را گم نکنی و یک کلمه را به همان شکلی که می‌شنوی بنویسی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"1"},{"label":{"en":"Word limit","tr":"Kelime sınırı","fa":"سقف کلمه"},"value":{"en":"1 word","tr":"1 kelime","fa":"۱ کلمه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: budget airlines","tr":"Bu sınav: ucuz havayolları","fa":"این آزمون: ایرلاین‌های ارزان"},"intro":{"en":"Part 4 is one academic talk: a lecture or a student presentation. Topics about society, business and health come up often. The notes copy the order of the talk, and the answers are said in the speaker’s words, not the notes’ words.","tr":"Part 4 tek bir akademik konuşmadır: bir ders ya da öğrenci sunumu. Toplum, işletme ve sağlık konuları sık çıkar. Notlar konuşmanın sırasını izler ve cevaplar notların değil konuşanın kelimeleriyle söylenir.","fa":"Part 4 یک صحبت دانشگاهی است: یک سخنرانی یا ارائه‌ی یک دانشجو. موضوع‌های جامعه، کسب‌وکار و سلامت زیاد می‌آیند. یادداشت‌ها ترتیب صحبت را دنبال می‌کنند و جواب‌ها با کلمه‌های گوینده گفته می‌شوند، نه کلمه‌های یادداشت."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x02-l4-ctx","exam":true,"patterns":["L4-society","PARA-signpost"],"often":{"pattern":"L4-society","n":10,"of":40,"label":{"en":"Comes up often in the real exam: 10 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 10’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۱۰ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"A presentation on budget airlines","tr":"Ucuz havayolları üzerine bir sunum","fa":"ارائه‌ای درباره‌ی ایرلاین‌های ارزان"},"asks":{"en":"A student gives a business presentation: how cheap airlines started, how they keep costs down, the problems they cause and their future. The notes follow her four sections.","tr":"Bir öğrenci işletme dersinde sunum yapıyor: ucuz havayollarının nasıl başladığı, maliyetleri nasıl düşük tuttukları, yol açtıkları sorunlar ve gelecekleri. Notlar onun dört bölümünü izler.","fa":"یک دانشجو در درس بازرگانی ارائه می‌دهد: ایرلاین‌های ارزان چطور شروع شدند، چطور هزینه‌ها را پایین نگه می‌دارند، چه مشکل‌هایی درست کرده‌اند و آینده‌شان چیست. یادداشت‌ها چهار بخشِ حرف او را دنبال می‌کنند."},"fields":["Origins","Keeping costs low","Problems","The future"],"words":[{"a":"budget airline","b":"low-cost carrier / cheap airline","tr":"ucuz havayolu","fa":"ایرلاین ارزان"},{"a":"fare","b":"ticket price","tr":"bilet ücreti","fa":"کرایه، قیمت بلیت"},{"a":"compete on price","b":"sell cheaper than others","tr":"fiyatla rekabet etmek","fa":"رقابت قیمتی"},{"a":"spare parts","b":"pieces kept to repair machines","tr":"yedek parça","fa":"قطعه‌ی یدکی"},{"a":"landing fee","b":"what an airport charges an airline","tr":"iniş ücreti","fa":"هزینه‌ی فرود"},{"a":"turnaround","b":"the time between landing and taking off again","tr":"iki uçuş arası hazırlık süresi","fa":"فاصله‌ی فرود تا پرواز بعدی"},{"a":"sold separately","b":"you pay extra for it","tr":"ayrıca satılır","fa":"جداگانه فروخته می‌شود"},{"a":"contract","b":"the agreement you sign with an employer","tr":"sözleşme","fa":"قرارداد"},{"a":"regulator","b":"the official body that sets the rules","tr":"düzenleyici kurum","fa":"نهاد ناظر"},{"a":"emissions","b":"carbon / the gases that are produced","tr":"salımlar","fa":"گازهای خروجی"},{"a":"legroom","b":"space for your legs","tr":"diz mesafesi","fa":"فضای پا"},{"a":"long-haul","b":"long-distance","tr":"uzun mesafeli","fa":"مسیر طولانی"}],"traps":[{"en":"\"You might think the main cost is X, but in fact...\" The note wants what comes after \"in fact\".","tr":"\"Ana maliyetin X olduğunu düşünebilirsin, ama aslında...\" Not, \"aslında\"dan sonra geleni ister.","fa":"«شاید فکر کنی هزینه‌ی اصلی X است، اما در واقع...». یادداشت چیزی را می‌خواهد که بعد از «در واقع» می‌آید."},{"en":"Plural nouns: the speaker says \"airports\" or \"charges\". Keep the s; the word limit counts words, not letters.","tr":"Çoğul isimler: konuşan \"airports\" ya da \"charges\" der. s’yi koru; kelime sınırı harfleri değil kelimeleri sayar.","fa":"اسم‌های جمع: گوینده می‌گوید «airports» یا «charges». s را نگه دار؛ سقف کلمه کلمه‌ها را می‌شمارد، نه حرف‌ها را."}],"example":{"text":"\"Most of these companies make their money from the extras rather than the seat itself.\"","item":"Main source of income: ___ (ONE WORD ONLY)","answer":"extras","why":{"en":"\"Rather than the seat\" rules the seat out; the plural extras is copied as you hear it.","tr":"\"Koltuğun kendisinden çok\" koltuğu dışarıda bırakıyor; çoğul extras duyduğun gibi yazılır.","fa":"«به جای خودِ صندلی» صندلی را رد می‌کند؛ extras را به همان شکل جمعی که می‌شنوی بنویس."}}},{"id":"L4-society","ctx":["L4-society"],"title":{"en":"Society, health and business","tr":"Toplum, sağlık ve iş dünyası","fa":"جامعه، سلامت و کسب‌وکار"},"asks":{"en":"A presenter reports research on people: health, memory, music therapy, food trends, design for everyone or the workplace. The notes cover the problem, the study, the findings and what should change.","tr":"Bir sunucu insanlarla ilgili bir araştırmayı aktarır: sağlık, hafıza, müzik terapisi, yiyecek trendleri, herkes için tasarım ya da iş yeri. Notlar sorunu, çalışmayı, bulguları ve neyin değişmesi gerektiğini kapsar.","fa":"یک ارائه‌دهنده پژوهشی درباره‌ی آدم‌ها را گزارش می‌کند: سلامت، حافظه، موسیقی‌درمانی، روندهای غذایی، طراحی برای همه یا محیط کار. یادداشت‌ها مسئله، پژوهش، یافته‌ها و تغییرات لازم را پوشش می‌دهند."},"fields":["Background","Method","Participants","Findings","Benefits","Limitations","Recommendations"],"words":[{"a":"participants","b":"the people in the study / volunteers","tr":"katılımcılar","fa":"شرکت‌کننده‌ها"},{"a":"findings","b":"what the study showed","tr":"bulgular","fa":"یافته‌ها"},{"a":"therapy","b":"treatment","tr":"terapi","fa":"درمان"},{"a":"patients","b":"people in hospital","tr":"hastalar","fa":"بیماران"},{"a":"recovery","b":"getting better after an illness","tr":"iyileşme","fa":"بهبودی"},{"a":"stress","b":"feeling under pressure","tr":"stres","fa":"استرس"},{"a":"consumers","b":"shoppers / people who buy","tr":"tüketiciler","fa":"مصرف‌کننده‌ها"},{"a":"trend","b":"what's becoming popular","tr":"eğilim","fa":"روند"},{"a":"productivity","b":"how much work gets done","tr":"verimlilik","fa":"بهره‌وری"},{"a":"accessible","b":"easy for everyone to use","tr":"erişilebilir","fa":"قابل دسترس"},{"a":"elderly","b":"older people","tr":"yaşlılar","fa":"سالمندان"},{"a":"limitation","b":"what the study didn't look at","tr":"sınırlılık","fa":"محدودیت"},{"a":"recommend","b":"the speaker suggests","tr":"önermek","fa":"توصیه کردن"}],"traps":[{"en":"Check the group: \"older patients\" and \"all patients\" can have different answers.","tr":"Grubu kontrol et: \"yaşlı hastalar\" ile \"bütün hastalar\" farklı cevaplara sahip olabilir.","fa":"گروه را چک کن: «بیماران مسن» و «همه‌ی بیماران» ممکن است جواب‌های متفاوتی داشته باشند."},{"en":"Findings and limitations sound alike: \"the study showed X, but it didn’t look at Y\". Read the heading.","tr":"Bulgular ve sınırlılıklar birbirine benzer: \"çalışma X’i gösterdi ama Y’ye bakmadı\". Başlığı oku.","fa":"یافته‌ها و محدودیت‌ها شبیه هم‌اند: «پژوهش X را نشان داد، ولی Y را بررسی نکرد». عنوان را بخوان."}],"example":{"lines":[["Lecturer","Patients who listened to music before surgery needed less medication afterwards."],["Lecturer","Interestingly, the type of music made no difference."],["Lecturer","What mattered was that patients chose it themselves."]],"item":"Key factor: patients ___ the music themselves   (ONE WORD ONLY)","answer":"chose","why":{"en":"The type of music \"made no difference\". \"What mattered\" introduces the answer: chose.","tr":"Müziğin türü \"fark yaratmadı\". \"What mattered\" cevabı getiriyor: chose.","fa":"نوع موسیقی «فرقی نداشت». «What mattered» جواب را می‌آورد: chose."}},"general":true,"patterns":["L4-society"],"often":{"pattern":"L4-society","n":10,"of":40,"label":{"en":"Comes up often in the real exam: 10 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 10’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۱۰ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Ten notes, no break","tr":"On not, ara yok","fa":"ده یادداشت، بدون مکث"},"body":{"en":"Questions 31-40 are notes under four or five headings. You have about 45 seconds to read them, then the talk plays once without a break. Write ONE WORD ONLY: no numbers, and nothing that is already printed.","tr":"Soru 31-40, dört beş başlık altındaki notlardır. Onları okumak için yaklaşık 45 saniyen var, sonra konuşma arasız bir kez çalınır. ONE WORD ONLY yaz: sayı yok ve zaten yazılı olan hiçbir şey yok.","fa":"سؤال‌های ۳۱ تا ۴۰ یادداشت‌هایی زیر چهار پنج عنوان‌اند. حدود ۴۵ ثانیه برای خواندنشان وقت داری و بعد صحبت یک بار و بدون مکث پخش می‌شود. ONE WORD ONLY بنویس: نه عدد و نه چیزی که از قبل چاپ شده."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Let the signposts guide you","tr":"Yön gösteren ifadeler sana yol göstersin","fa":"بگذار جمله‌های راهنما راهت را نشان دهند"},"steps":[{"en":"Read the headings first: they are the map of the talk.","tr":"Önce başlıkları oku: konuşmanın haritası onlardır.","fa":"اول عنوان‌ها را بخوان: آن‌ها نقشه‌ی صحبت‌اند."},{"en":"Listen for signposts such as \"Let’s start with\", \"Moving on to\", \"Turning now to\" and \"Finally\", and move to the next heading when you hear one.","tr":"\"Let’s start with\", \"Moving on to\", \"Turning now to\" ve \"Finally\" gibi ifadelere kulak ver; birini duyunca bir sonraki başlığa geç.","fa":"به جمله‌های راهنما مثل «Let’s start with»، «Moving on to»، «Turning now to» و «Finally» گوش بده و وقتی یکی را شنیدی برو سراغ عنوان بعدی."},{"en":"For each gap, decide the word class from the printed words: after \"on the\" you need a noun.","tr":"Her boşluk için kelime türünü yazılı kelimelerden çıkar: \"on the\"dan sonra bir isim gerekir.","fa":"برای هر جای خالی نوع کلمه را از کلمه‌های چاپ‌شده بفهم: بعد از «on the» یک اسم لازم است."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"The word you hear, not the word you expect","tr":"Beklediğin kelime değil, duyduğun kelime","fa":"کلمه‌ای که می‌شنوی، نه کلمه‌ای که انتظار داری"},"body":{"en":"The notes paraphrase the talk, but the answer is the speaker’s own word. If you hear a plural, write a plural. If a phrase has three words, find the one word that fits the gap.","tr":"Notlar konuşmayı başka kelimelerle anlatır ama cevap konuşanın kendi kelimesidir. Çoğul duyarsan çoğul yaz. Bir ifade üç kelimeyse boşluğa uyan tek kelimeyi bul.","fa":"یادداشت‌ها صحبت را با کلمه‌های دیگر می‌گویند، اما جواب کلمه‌ی خودِ گوینده است. اگر جمع شنیدی، جمع بنویس. اگر عبارتی سه کلمه است، آن یک کلمه‌ای را پیدا کن که در جای خالی جا می‌شود."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One note, step by step","tr":"Bir not, adım adım","fa":"یک یادداشت، قدم به قدم"},"instruction":"Complete the notes below. Write ONE WORD ONLY for each answer.","item":"Railways in the 1950s · many lines closed because of competition from ___","lines":[["Lecturer","You might expect the main reason to be cost. In fact, many lines closed because more and more families now owned cars."]],"answer":"cars","walk":[{"en":"The gap follows \"competition from\", so it needs a noun.","tr":"Boşluk \"competition from\"dan sonra geliyor; bir isim gerekiyor.","fa":"جای خالی بعد از «competition from» است، پس یک اسم لازم است."},{"en":"Cost is mentioned first, then ruled out by \"In fact\".","tr":"Önce maliyetten söz ediliyor, sonra \"In fact\" ile eleniyor.","fa":"اول از هزینه حرف زده می‌شود و بعد با «In fact» رد می‌شود."},{"en":"Families owning cars is the competition. Write cars, plural, as you hear it.","tr":"Rekabet, ailelerin araba sahibi olması. Duyduğun gibi çoğul yaz: cars.","fa":"رقیب این است که خانواده‌ها ماشین داشتند. cars را جمع بنویس، همان‌طور که می‌شنوی."}]},"quick":{"prompt":"Note: \"the museum attracts families with free ___\" (ONE WORD ONLY). You hear: \"What really brings families in is the free workshops at weekends.\" What do you write?","options":["weekends","workshops","free workshops"],"correct":1,"why":{"en":"\"free\" is printed, so write one word: workshops, plural as you hear it. Weekends is when, not what.","tr":"\"free\" yazılı, tek kelime yaz: workshops, duyduğun gibi çoğul. Weekends ne zaman olduğunu söyler, ne olduğunu değil.","fa":"«free» چاپ شده، پس یک کلمه بنویس: workshops، جمع همان‌طور که می‌شنوی. weekends زمان را می‌گوید، نه چیز را."}},"remember":{"en":"Follow the headings with the signposts, and write the speaker’s one word in the form you hear it.","tr":"Başlıkları yön gösteren ifadelerle takip et ve konuşanın tek kelimesini duyduğun biçimde yaz.","fa":"عنوان‌ها را با جمله‌های راهنما دنبال کن و یک کلمه‌ی گوینده را به همان شکلی که می‌شنوی بنویس."},"type":"explain","id":"c-x02-l4-e","course":"ielts-exams","exam":"exam-02","unit":"x02-l4"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 4","title":{"en":"Budget airlines","tr":"Ucuz havayolları","fa":"ایرلاین‌های ارزان"},"timed":8,"ctx":["L4-society"],"script":[{"who":"Presenter","line":"Good morning, everyone. For my presentation in this business module, I've chosen to look at budget airlines: how they started, how they keep their prices so low, the problems they've created, and what might happen to them in the future."},{"who":"Presenter","line":"Let's start with the origins. The first airlines to sell very cheap tickets appeared in the United States in the nineteen seventies, but for a long time they stayed small. In most countries the government decided how much an air ticket could cost, so no company could really compete on price. Everything changed when governments removed their controls on ticket prices. Once airlines could set their own fares, a new kind of company appeared almost overnight, and within twenty years budget carriers were flying more passengers within Europe than the traditional national airlines."},{"who":"Presenter","line":"Moving on to how these airlines keep their costs so low. You might think the secret is simply paying less for fuel, but in fact every airline pays roughly the same for fuel. The real savings come from the way the business is organised. First, a budget airline usually flies only one model of aircraft. That means its pilots, cabin crew and mechanics only need to be trained on one type, and the company can keep a much smaller stock of spare parts."},{"who":"Presenter","line":"Second, instead of the big international hubs, these airlines tend to use smaller, secondary airports, often an hour or more from the city they're named after. Those airports charge much lower landing fees, and many of them are so keen to attract passengers that they offer extra discounts in the first few years."},{"who":"Presenter","line":"Third, there's speed. An aircraft only earns money when it's in the air, so budget airlines try to keep each plane on the ground for as little time as possible. A traditional airline might take an hour to unload, clean and refuel a plane. A budget airline aims to do it in about twenty-five minutes, which allows each plane to make one or two extra flights a day."},{"who":"Presenter","line":"And finally, the ticket price itself covers only the seat. Almost everything else is sold separately. Passengers pay extra for checked luggage, for choosing a seat, for food and drink on board, and sometimes even for printing a boarding pass at the airport. For many of these companies, these extras now bring in a large share of their income."},{"who":"Presenter","line":"Turning now to the problems. The first concerns the people who work for these airlines. Cabin crew are often employed through agencies, on short contracts, and their wages are generally lower than at traditional airlines. Several budget carriers have faced strikes in recent years, and in some countries the courts have ruled that crew should be treated as full employees."},{"who":"Presenter","line":"Passengers have complaints too. The most common one isn't about comfort or delays, as you might expect. It's about hidden charges: the price you see at the start of a booking is very rarely the price you end up paying. Consumer groups have pushed for the full price to be shown from the first screen, and some regulators now require this."},{"who":"Presenter","line":"The third problem is environmental. Because tickets are so cheap, budget airlines have encouraged a huge growth in short flights, including many journeys that could easily be made by train. Per passenger, a short flight produces far more carbon than the same journey by rail, so critics argue that these companies have made a habit of flying that the planet can't afford."},{"who":"Presenter","line":"So what does the future look like? Some governments have started to act. A few European countries now ban short flights on routes where a train can do the journey in a few hours. The airlines, for their part, say they're trying to clean up. Several are testing aircraft fuel made from used cooking oil and other kinds of waste, which can cut emissions considerably. The difficulty is that this fuel is still very expensive and only produced in small amounts."},{"who":"Presenter","line":"Some people expected budget airlines to take over long-distance routes as well, but so far most attempts have failed. The low-cost model works on a two-hour flight, but on a twelve-hour journey passengers want comfort: proper meals, more legroom and the chance to sleep. Those are exactly the things a budget airline is designed to remove. So my conclusion is that budget airlines will remain very important for short and medium journeys, but they'll face growing pressure from trains and from governments. Thank you very much for listening. I'm happy to take any questions now."}],"notes":{"title":"Budget airlines","headings":["Origins","Keeping costs low","Problems","The future"],"extra":["The future · some countries ban short flights where a train can make the journey in a few hours"]},"groups":[{"instruction":"Questions 31-40. Complete the notes below. Write ONE WORD ONLY for each answer.","qtype":"note","questions":[{"n":31,"kind":"gap","prompt":"Origins · cheap fares became possible when governments removed their ___ on ticket prices","accept":["controls"],"limit":1,"evidence":"governments removed their controls on ticket prices","why":{"en":"\"Everything changed when governments removed their controls on ticket prices.\" Plural, as you hear it.","tr":"\"Hükümetler bilet fiyatları üzerindeki denetimlerini kaldırınca her şey değişti.\" Duyduğun gibi çoğul.","fa":"«وقتی دولت‌ها کنترل‌هایشان را روی قیمت بلیت برداشتند همه‌چیز عوض شد». جمع، همان‌طور که می‌شنوی."},"trap":["TR-plural","TR-paraphrase"]},{"n":32,"kind":"gap","prompt":"Keeping costs low · only one model of ___ in the fleet","accept":["aircraft"],"limit":1,"evidence":"flies only one model of aircraft","why":{"en":"Fuel costs about the same for everyone. The saving comes from flying \"only one model of aircraft\".","tr":"Yakıt herkes için aşağı yukarı aynı. Tasarruf \"yalnızca tek bir uçak modeli\" kullanmaktan geliyor.","fa":"سوخت برای همه تقریباً یک قیمت است. صرفه‌جویی از این است که «فقط یک مدل هواپیما» دارند."},"trap":["TR-paraphrase"]},{"n":33,"kind":"gap","prompt":"Keeping costs low · fly to less busy ___ with low landing fees","accept":["airports"],"limit":1,"evidence":"smaller, secondary airports","why":{"en":"\"Smaller, secondary airports\" = less busy. Write airports, with the s.","tr":"\"Daha küçük, ikincil havalimanları\" = daha az yoğun. airports’u s ile yaz.","fa":"«فرودگاه‌های کوچک‌تر و درجه‌دو» یعنی کم‌رفت‌وآمدتر. airports را با s بنویس."},"trap":["TR-plural","TR-paraphrase"]},{"n":34,"kind":"gap","prompt":"Keeping costs low · each plane spends very little time on the ___","accept":["ground"],"limit":1,"evidence":"on the ground for as little time as possible","why":{"en":"A plane earns money only in the air, so they keep it \"on the ground for as little time as possible\".","tr":"Uçak yalnızca havadayken para kazanır; bu yüzden onu \"yerde mümkün olduğunca az\" tutuyorlar.","fa":"هواپیما فقط در هوا پول درمی‌آورد، پس آن را «تا جای ممکن کم روی زمین» نگه می‌دارند."},"trap":["TR-paraphrase"]},{"n":35,"kind":"gap","prompt":"Keeping costs low · passengers pay extra for checked ___ and for choosing a seat","accept":["luggage"],"limit":1,"evidence":"Passengers pay extra for checked luggage","why":{"en":"\"Passengers pay extra for checked luggage.\" \"checked\" is printed, so one word is enough.","tr":"\"Yolcular kayıtlı bagaj için ek ücret öder.\" \"checked\" yazılı, tek kelime yeter.","fa":"«مسافرها برای بارِ تحویلی پول اضافه می‌دهند». «checked» چاپ شده، پس یک کلمه کافی است."},"trap":["TR-limit"]},{"n":36,"kind":"gap","prompt":"Problems · cabin crew: short contracts and lower ___","accept":["wages"],"limit":1,"evidence":"their wages are generally lower","why":{"en":"\"Their wages are generally lower than at traditional airlines.\" Plural: wages.","tr":"\"Ücretleri genelde geleneksel havayollarından düşük.\" Çoğul: wages.","fa":"«دستمزدشان معمولاً از ایرلاین‌های سنتی کمتر است». جمع: wages."},"trap":["TR-plural"]},{"n":37,"kind":"gap","prompt":"Problems · passengers: the main complaint is about extra ___ not shown at first","accept":["charges"],"limit":1,"evidence":"It's about hidden charges","why":{"en":"Not comfort or delays, \"as you might expect\": \"It’s about hidden charges\".","tr":"\"Beklediğin gibi\" konfor ya da gecikmeler değil: \"Gizli ücretlerle ilgili\".","fa":"«آن‌طور که انتظار داری» راحتی یا تأخیر نیست: «درباره‌ی هزینه‌های پنهان است»."},"trap":["TR-plural","TR-paraphrase"]},{"n":38,"kind":"gap","prompt":"Problems · a big increase in short ___, many of which could be made by train","accept":["flights"],"limit":1,"evidence":"a huge growth in short flights","why":{"en":"\"A huge growth in short flights\" = a big increase. Keep the plural.","tr":"\"Kısa uçuşlarda büyük bir artış\" = büyük bir artış. Çoğulu koru.","fa":"«رشد بزرگی در پروازهای کوتاه» یعنی افزایش زیاد. جمع را نگه دار."},"trap":["TR-plural"]},{"n":39,"kind":"gap","prompt":"The future · tests of aircraft fuel made from used cooking ___ and other waste","accept":["oil"],"limit":1,"evidence":"fuel made from used cooking oil","why":{"en":"\"Aircraft fuel made from used cooking oil and other kinds of waste.\"","tr":"\"Kullanılmış kızartma yağından ve başka atıklardan yapılan uçak yakıtı.\"","fa":"«سوخت هواپیما که از روغنِ سرخ‌کردنیِ مصرف‌شده و پسماندهای دیگر ساخته می‌شود»."},"trap":["TR-limit"]},{"n":40,"kind":"gap","prompt":"The future · long-distance budget routes mostly fail: passengers want ___","accept":["comfort"],"limit":1,"evidence":"passengers want comfort","why":{"en":"\"On a twelve-hour journey passengers want comfort\": meals, legroom, sleep.","tr":"\"On iki saatlik bir yolculukta yolcular konfor ister\": yemek, diz mesafesi, uyku.","fa":"«در سفر دوازده‌ساعته مسافرها راحتی می‌خواهند»: غذا، فضای پا، خواب."},"trap":["TR-paraphrase"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Presenter":{"accent":"Australian","gender":"F","tts":{"engine":"kokoro","voice":"af_nicole","fallback":true,"note":"Australian wanted; no free Australian voice yet"},"role":"Student presenter"}},"sequence":[{"type":"announcer","text":"Part 4. You will hear a student giving a presentation about budget airlines. First, you have some time to look at Questions 31 to 40."},{"type":"pause","seconds":45,"note":"reading time, Questions 31-40"},{"type":"announcer","text":"Now listen carefully and answer Questions 31 to 40."},{"type":"sfx","note":"seminar-room acoustics: slight room reverb; 1.5 s between paragraphs"},{"type":"lines","from":0,"to":10},{"type":"announcer","text":"That is the end of Part 4. You now have two minutes to check your answers.","after":120}]},"id":"c-x02-l4-d","course":"ielts-exams","exam":"exam-02","unit":"x02-l4"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"In a talk about air travel, the \"fare\" is...","options":["the price of a ticket","the weight of a bag","the length of a flight"],"correct":0,"why":{"en":"A fare is the money you pay to travel.","tr":"Fare, yolculuk için ödediğin paradır.","fa":"fare پولی است که برای سفر می‌دهی."}},{"tests":"paraphrase","point":1,"prompt":"\"Most planes are turned around in under half an hour.\" Which note means the same?","options":["planes fly for less than thirty minutes","planes often arrive late","planes spend little time at the airport between flights"],"correct":2,"why":{"en":"Turnaround = the time on the ground between landing and the next take-off.","tr":"Turnaround = iniş ile bir sonraki kalkış arasında yerde geçen süre.","fa":"turnaround یعنی مدتی که هواپیما بین فرود و پرواز بعدی روی زمین است."}},{"tests":"method","point":2,"prompt":"The speaker says \"Turning now to the problems.\" What should you do?","options":["stop and check your earlier answers","move your eyes to the Problems heading","go back to the first heading"],"correct":1,"why":{"en":"A signpost tells you the talk has reached the next heading.","tr":"Yön gösteren ifade, konuşmanın bir sonraki başlığa geçtiğini söyler.","fa":"جمله‌ی راهنما می‌گوید صحبت به عنوان بعدی رسیده."}},{"tests":"trap","point":3,"prompt":"Note: \"staff complain about low ___\" (ONE WORD ONLY). You hear: \"Their salaries are well below average.\" What do you write?","options":["salaries","salary","low salaries"],"correct":0,"why":{"en":"\"low\" is printed. Write the plural you hear: salaries.","tr":"\"low\" yazılı. Duyduğun çoğulu yaz: salaries.","fa":"«low» چاپ شده. جمعی را که می‌شنوی بنویس: salaries."}},{"tests":"trap","point":3,"prompt":"\"You might think the biggest cost is fuel, but actually it’s staff.\" Note: \"largest cost: ___\". What do you write?","options":["fuel","fuel and staff","staff"],"correct":2,"why":{"en":"\"You might think...\" introduces the wrong idea; \"but actually\" gives the answer.","tr":"\"Düşünebilirsin...\" yanlış fikri getirir; \"ama aslında\" cevabı verir.","fa":"«شاید فکر کنی...» ایده‌ی غلط را می‌آورد؛ «اما در واقع» جواب را می‌دهد."}}],"id":"c-x02-l4-x","course":"ielts-exams","exam":"exam-02","unit":"x02-l4"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
